from robot.utils.robottime import timestr_to_secs

from ..validators import IsString

from .base import BaseInterface
from ..util import wrap_result


class PMCountersInterface(BaseInterface):

    @wrap_result
    def get_kpi(self, object_name="", kpi_id="", timeout=60, alias="default"):
        """Get KPI.

        :param string object_name: the object from which the KPI value was calculated
        :param string kpi_id: the id of a kpi returns the value only for this particular kpi
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: dictionary
        :return: returns the values for all the KPIs
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(object_name)
        IsString().check(kpi_id)

        request_message = self.store.get(alias).execute_infomodel_request("getKpi", {"object": object_name, "id": kpi_id}, timeout)
        return request_message

    @wrap_result
    def get_measurements(self, object_name="", kpi_id="", timeout=60, alias="default"):
        """Get Measurements.

        :param string object_name: the object from which the KPI value was calculated
        :param string kpi_id: the id of a kpi returns the value only for this particular kpi
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: list
        :return: list of real time measurements RnD counters such as energy, VSWR, hardware monitoring,
        temperature, ram, disk, cpu etc. real time measurements.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(object_name)
        IsString().check(kpi_id)
        return self.store.get(alias).execute_infomodel_request("getMeasurements", {"object": object_name, "id": kpi_id}, timeout)

    @wrap_result
    def get_pm_counters_by_dist_name(self, dist_name="all", timeout=60, alias="default"):
        """Get PM counters by dist name.
        :param string dist_name: Counter dist name | all
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: list
        :return: list of matching PM counters
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        return self.store.get(alias).execute_infomodel_request("getCounters", {"distName": dist_name}, timeout)

    @wrap_result
    def get_pm_counters(self, couter_ids="", timeout=60, alias="default"):
        """Get PM counters by IDs.
        :param string couter_ids: Couter IDs (splited by comma). Empty string matches all.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: list
        :return: list of matching PM counters
        """
        timeout = timestr_to_secs(timeout)

        couter_ids = couter_ids.split(",") if couter_ids else "all"
        return self.store.get(alias).execute_infomodel_request("getCounters", {"counterIds": couter_ids}, timeout,)
